enum {
	LEVEL_LAST = 32,
	BEACH_LAST = 13,
	MAP_LOC_LAST = 14,
	MAX_GOALS_PER_LEVEL = 5,
	SURFER_KELLY_SLATER = 0,
	GOAL_ENV_SPRAY_WINDSURFERS = 41,
	GOAL_ENV_JUMP_PIER = 48
};

struct ksConfigData {
	char data[0x4c];
};

struct StoredConfigData {
	static StoredConfigData *inst();
	void *getGameConfig();
};

struct Career {
	struct Level {
		void SetMyId(int);
	};
	struct Beach {
		void SetMyId(int);
	};
	struct Location {
		void SetMyId(int);
	};

	char prefix[0x24];
	ksConfigData cfg;
	Level levels[LEVEL_LAST];
	Beach beaches[BEACH_LAST];
	Location locations[MAP_LOC_LAST];
	bool new_goal_passed[MAX_GOALS_PER_LEVEL];
	bool goal_passed[MAX_GOALS_PER_LEVEL];
	bool awarded[MAX_GOALS_PER_LEVEL];
	int total_env_challenges;
	int env_challenges_passed;
	int super_board_was_unlocked;
	int bails_movie_was_unlocked;
	int espn_movie_was_unlocked;
	int levels_completed_order[LEVEL_LAST];

	void SetMyId(int);
	void StartNewCareer();
	void init();
};

struct CareerData {
	char prefix[0x70];
	int goal[MAX_GOALS_PER_LEVEL];
	char suffix[0x58];
};

extern CareerData CareerDataArray[];

void Career::init()
{
	int i, j;
	//bool level_available;

	for(j = 0; j < LEVEL_LAST; j++)
		levels[j].SetMyId(j);
	for(j = 0; j < BEACH_LAST; j++)
		beaches[j].SetMyId(j);
	for(j = 0; j < MAP_LOC_LAST; j++)
		locations[j].SetMyId(j);

	for (j=0; j < MAX_GOALS_PER_LEVEL; j++)
	{
		new_goal_passed[j] = false;
		goal_passed[j] = false;
		awarded[j] = false;
	}
	SetMyId(SURFER_KELLY_SLATER);
	StartNewCareer(); // we do this just to make sure we don't inadvertently use weird data

	cfg = *(ksConfigData *)StoredConfigData::inst()->getGameConfig();

	// count up the environmental challenges
	total_env_challenges = 0;
	env_challenges_passed = 0;
	super_board_was_unlocked = -1;
	bails_movie_was_unlocked = -1;
	espn_movie_was_unlocked  = -1;

	for(i = 0; i < LEVEL_LAST; i++)
	{
		levels_completed_order[i] = -1;

		for(j = 0; j < MAX_GOALS_PER_LEVEL; j++)
			// if it's an environmental challenge
			if(CareerDataArray[i].goal[j] >= GOAL_ENV_SPRAY_WINDSURFERS && 
			   CareerDataArray[i].goal[j] <= GOAL_ENV_JUMP_PIER)
			{
				total_env_challenges++;
			}
	}
}
